forgetRecords(ids: string[], filter: IsolationFilter): void {
  this.db.exec("BEGIN IMMEDIATE");
  try {
    for (const id of ids) {
      const row = this.stmtGetMeta.get(id) as any;
      if (row && !rowMatchesIsolation(row, filter)) throw new Error("DELETE_SCOPE_CONFLICT");
      this.deleteControlledRecord(id);
    }
    this.db.exec("COMMIT");
  } catch (error) { this.db.exec("ROLLBACK"); throw error; }
}

